CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_pages_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES library_documents(id),source_run_id TEXT NOT NULL,pdf_page INT NOT NULL,page_status TEXT NOT NULL,raw_text TEXT NOT NULL,normalized_text TEXT NOT NULL,text_hash TEXT NOT NULL,has_hebrew BOOL NOT NULL,has_latin BOOL NOT NULL,reading_order_method TEXT NOT NULL,warnings JSONB NOT NULL DEFAULT '[]',UNIQUE(source_run_id,pdf_page));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_page_blocks_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL REFERENCES library_documents(id),source_run_id TEXT NOT NULL,pdf_page INT NOT NULL,block_index INT NOT NULL,bbox JSONB NOT NULL,text TEXT NOT NULL,normalized_text TEXT NOT NULL,text_hash TEXT NOT NULL,role TEXT NOT NULL,UNIQUE(source_run_id,pdf_page,block_index));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_structural_classifications_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL,run_id TEXT NOT NULL,pdf_page INT NOT NULL,document_part TEXT NOT NULL,structural_status TEXT NOT NULL,unit_type TEXT NOT NULL,evidence_quote TEXT,confidence NUMERIC NOT NULL,UNIQUE(run_id,pdf_page));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_fine_zones_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL,run_id TEXT NOT NULL,pdf_page INT NOT NULL,block_id UUID,zone_type TEXT NOT NULL,text_quote TEXT NOT NULL,quote_hash TEXT NOT NULL,validation_status TEXT NOT NULL,confidence NUMERIC NOT NULL,UNIQUE(run_id,pdf_page,block_id));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_note_source_units_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL,run_id TEXT NOT NULL,pdf_page INT NOT NULL,unit_type TEXT NOT NULL,visible_note_number TEXT,text_quote TEXT NOT NULL,validation_status TEXT NOT NULL,UNIQUE(run_id,pdf_page,visible_note_number));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_nominal_references_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),document_id UUID NOT NULL,run_id TEXT NOT NULL,pdf_page INT NOT NULL,surface_form TEXT NOT NULL,normalized_reference_name TEXT,reference_kind TEXT NOT NULL,text_quote TEXT NOT NULL,validation_status TEXT NOT NULL,UNIQUE(run_id,pdf_page,surface_form,text_quote));
CREATE TABLE IF NOT EXISTS library_la_potencia_plegaria_nominal_reference_resolution_v1 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),nominal_reference_id UUID NOT NULL,run_id TEXT NOT NULL,resolution_decision TEXT NOT NULL,resolution_method TEXT NOT NULL,confidence NUMERIC NOT NULL,UNIQUE(run_id,nominal_reference_id));
CREATE OR REPLACE VIEW library_la_potencia_plegaria_page_first_v1 AS SELECT * FROM library_la_potencia_plegaria_pages_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_search_ready_v1 AS SELECT * FROM library_la_potencia_plegaria_pages_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_structural_v1 AS SELECT * FROM library_la_potencia_plegaria_structural_classifications_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_search_ready_v2 AS SELECT p.*,s.document_part,s.structural_status,s.unit_type,s.evidence_quote structural_quote FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_fine_zones_search_v1 AS SELECT * FROM library_la_potencia_plegaria_fine_zones_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_search_ready_v3 AS SELECT p.*,s.document_part,s.structural_status,z.id fine_zone_id,z.zone_type,z.text_quote,z.validation_status FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page LEFT JOIN library_la_potencia_plegaria_fine_zones_v1 z ON z.document_id=p.document_id AND z.pdf_page=p.pdf_page;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_note_source_search_v1 AS SELECT * FROM library_la_potencia_plegaria_note_source_units_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_nominal_reference_search_v1 AS SELECT * FROM library_la_potencia_plegaria_nominal_references_v1;
CREATE OR REPLACE VIEW library_la_potencia_plegaria_investigative_search_v1 AS SELECT p.pdf_page,p.page_status,s.document_part,s.structural_status,z.zone_type,z.text_quote quote,'fine_zone' search_record_type,'validated_zone' evidence_level FROM library_la_potencia_plegaria_pages_v1 p JOIN library_la_potencia_plegaria_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page JOIN library_la_potencia_plegaria_fine_zones_v1 z ON z.document_id=p.document_id AND z.pdf_page=p.pdf_page WHERE z.validation_status='validated';
CREATE OR REPLACE VIEW library_la_potencia_plegaria_investigative_audit_v1 AS SELECT * FROM library_la_potencia_plegaria_investigative_search_v1;
